const b = $input.first().json.body || {};
const key = $env.SEND_KEY || '';
const auth_ok = !!key && typeof b.key === 'string' && b.key === key;
const action = ['contacts', 'status', 'send'].includes(b.action) ? b.action : 'status';
const campaign = ['V','A1','A2','B1','B2','B3'].includes(b.campaign) ? b.campaign : 'V';
return [{ json: { ...b, key: undefined, auth_ok, action, campaign, video: !!b.video, dry_run: !!b.dry_run, force: !!b.force,
  limit: Math.max(1, Math.min(200, Number(b.limit) || 40)) } }];

const r = $('Route').first().json;
const files = { V: 'funnel-video-email.html', A1: 'funnel-a1-template.html', A2: 'funnel-a2-template.html', B1: 'funnel-b1-template.html', B2: 'funnel-b2-template.html', B3: 'funnel-b3-template.html' };
return [{ json: { path: '/files/docs/' + files[r.campaign] } }];

const SITE = 'https://borngifted.github.io/mokipops-reel/';
const FROM = $env.FUNNEL_FROM || 'moreflavor@mokipops.com';
const CAMPAIGNS = {
  V:  { segment: 'b2b',    file: 'funnel-video-email.html', subject: '12 years in 38 seconds 🍉', preview: 'Kid-founded, Atlanta-made, now on Faire. Press play.', video_builtin: true },
  A1: { segment: 'buyers', file: 'funnel-a1-template.html', subject: 'The pops got better since you left 🍉', preview: 'New flavors, same real fruit — and a way to never run out.' },
  A2: { segment: 'buyers', file: 'funnel-a2-template.html', subject: 'One case = your whole event, sorted', preview: '$53.50 for 24 pops. Offices, parties, teams, schools.' },
  B1: { segment: 'b2b',    file: 'funnel-b1-template.html', subject: 'A $2 pop your customers will pay $4 for', preview: 'All-natural, Atlanta-made, margin at every level.' },
  B2: { segment: 'b2b',    file: 'funnel-b2-template.html', subject: '120 cases, 3,000 pops, one Atlanta afternoon', preview: 'The activation playbook — staffed cart included.' },
  B3: { segment: 'b2b',    file: 'funnel-b3-template.html', subject: 'Should I close your file?', preview: 'One reply gets you the price sheet — or a call.' },
};
const VIDEO_TAG = `<video width="520" autoplay muted loop playsinline poster="${SITE}assets/funnel/funnel-poster.jpg" style="display:block;width:100%;max-width:520px;height:auto;border-radius:14px;"><source src="${SITE}assets/funnel/mokipops-wholesale-funnel.mp4" type="video/mp4"><img src="${SITE}assets/funnel/funnel-loop.gif" width="520" alt="MOKIPOPS — real fruit pops, made in Atlanta (tap to watch)" style="display:block;width:100%;max-width:520px;height:auto;border-radius:14px;border:0;"></video>`;
const VIDEO_BLOCK = `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td align="center" style="padding:8px 24px 18px;"><a href="${SITE}video.html?utm_source=email&utm_medium=email&utm_campaign=wholesale_funnel&utm_content=video" target="_blank" style="text-decoration:none;display:block;">${VIDEO_TAG}</a><p style="margin:10px 0 0;font-family:Helvetica,Arial,sans-serif;font-size:13px;color:#5A463B;">&#9654;&nbsp; <a href="${SITE}video.html?utm_source=email&utm_medium=email&utm_campaign=wholesale_funnel&utm_content=video_caption" target="_blank" style="color:#E23A23;text-decoration:underline;font-weight:700;">Watch the full 38 seconds</a> &nbsp;&middot;&nbsp; sound on</p></td></tr></table>`;
function render(campaign, tpl, contact, withVideo) {
  const c = CAMPAIGNS[campaign];
  const first = (contact.firstname || '').trim() || 'there';
  const unsub = `mailto:${FROM}?subject=${encodeURIComponent('Unsubscribe ' + contact.email)}`;
  let html = tpl;
  if (campaign === 'V') html = html.replace(/<img src="[^"]*funnel-preview\.gif"[\s\S]*?>/, VIDEO_TAG);
  html = html.replace(/<!--[\s\S]*?-->/g, '')
    .replace(/\{%\s*text[^%]*value="([^"]*)"[^%]*%\}/g, (_, v) => c.preview || v).replace(/\{%[\s\S]*?%\}/g, '')
    .replace(/\{\{\s*content\.name\s*\}\}/g, c.subject).replace(/\{\{\s*contact\.firstname\s*\}\}/g, first)
    .replace(/\{\{\s*unsubscribe_link(_all)?\s*\}\}/g, unsub)
    .replace(/\{\{\s*site_settings\.company_name\s*\}\}/g, 'MOKIPOPS').replace(/\{\{\s*site_settings\.company_city\s*\}\}/g, 'Atlanta')
    .replace(/\{\{\s*site_settings\.company_state\s*\}\}/g, 'GA').replace(/\{\{\s*site_settings\.company_country\s*\}\}/g, 'USA')
    .replace(/\{\{[^}]*\}\}/g, '').replace(/utm_source=hubspot/g, 'utm_source=email');
  if (withVideo && !c.video_builtin) {
    const m = html.match(/logo\.png[\s\S]*?<\/tr>/);
    html = m ? html.slice(0, m.index + m[0].length) + '<tr><td>' + VIDEO_BLOCK + '</td></tr>' + html.slice(m.index + m[0].length) : html.replace(/(<body[^>]*>)/, '$1' + VIDEO_BLOCK);
  }
  const text = html.replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<a [^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/gi, (_, h, t) => `${t.replace(/<[^>]+>/g, '').trim()} (${h})`)
    .replace(/<video[\s\S]*?<\/video>/g, `Watch the film: ${SITE}video.html`)
    .replace(/<\/(p|div|tr|h\d|li)>/gi, '\n').replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&#39;/g, "'").replace(/&quot;/g, '"').replace(/&middot;/g, '·').replace(/&#9654;/g, '▶')
    .replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
  return { subject: c.subject, html, text };
}

const req = $('Route').first().json;
const rows = $('Parse CSV').all().map(i => i.json).map(r => ({ ...r, email: (r.email || '').toLowerCase() }));
const logText = (() => { try { return $('Log → text').first().json.data || ''; } catch (e) { return ''; } })();
const tpl = $('Template → text').first().json.data || '';
const entries = [];
logText.split('\n').forEach(l => { if (!l.trim()) return; try { entries.push(JSON.parse(l)); } catch (e) {} });
const sent = {}; // campaign -> Set(email)
entries.forEach(r => { if (r.ok && r.email) (sent[r.campaign] = sent[r.campaign] || new Set()).add(String(r.email).toLowerCase()); });
const sentList = e => Object.keys(sent).filter(c => sent[c].has(e));

if (req.action === 'contacts') {
  const contacts = rows.map(r => ({ email: r.email, firstname: r.firstname, name: r.name, company: r.company, city: r.city, segment: r.segment, status: r.status || 'active', sent: sentList(r.email) }));
  const segments = {};
  contacts.forEach(c => { const s = segments[c.segment] = segments[c.segment] || { total: 0, active: 0 }; s.total++; if (c.status === 'active') s.active++; });
  return [{ json: { response: { ok: true, count: contacts.length, segments, contacts }, queue: [] } }];
}
if (req.action === 'status') {
  const counts = {};
  entries.forEach(r => { const c = counts[r.campaign] = counts[r.campaign] || { ok: 0, failed: 0, last_at: null }; if (r.ok) c.ok++; else c.failed++; if (!c.last_at || r.at > c.last_at) c.last_at = r.at; });
  const recent = entries.filter(r => !req.campaign_filter || r.campaign === req.campaign_filter).slice(-100).reverse();
  return [{ json: { response: { ok: true, counts, recent, total: entries.length }, queue: [] } }];
}
// action === 'send'
const camp = req.campaign;
const already = sent[camp] || new Set();
let picked = [], skipped = 0, mode;
if (req.to && req.to.email) {
  mode = 'single';
  const e = String(req.to.email).toLowerCase().trim();
  const known = rows.find(r => r.email === e) || {};
  picked = [{ ...known, email: e, firstname: (req.to.name || known.firstname || '').split(' ')[0], name: req.to.name || known.name || '', segment: known.segment || 'manual' }];
} else if (Array.isArray(req.emails) && req.emails.length) {
  mode = 'picked';
  const want = new Set(req.emails.map(x => String(x).toLowerCase().trim()));
  picked = rows.filter(r => want.has(r.email));
  want.forEach(e => { if (!rows.find(r => r.email === e)) picked.push({ email: e, firstname: '', name: '', segment: 'manual', status: 'active' }); });
  picked = picked.filter(r => (r.status || 'active') === 'active');
  if (!req.force) { const before = picked.length; picked = picked.filter(r => !already.has(r.email)); skipped = before - picked.length; }
} else {
  mode = 'segment';
  const seg = req.segment || CAMPAIGNS[camp].segment;
  const eligible = rows.filter(r => r.segment === seg && (r.status || 'active') === 'active');
  const unsent = eligible.filter(r => !already.has(r.email));
  skipped = eligible.length - unsent.length;
  picked = unsent.slice(0, req.limit);
}
const queue = picked.map(r => { const m = render(camp, tpl, r, req.video); return { email: r.email, name: r.name || '', segment: r.segment || '', campaign: camp, subject: m.subject, html: m.html, text: m.text }; });
const response = { ok: true, mode, campaign: camp, video: req.video || camp === 'V', dry_run: req.dry_run, count: queue.length, skipped_already_sent: skipped,
  recipients: queue.map(q => ({ email: q.email, name: q.name, segment: q.segment })), sample_subject: queue[0] ? queue[0].subject : CAMPAIGNS[camp].subject,
  sample_html: req.dry_run && queue[0] ? queue[0].html : undefined, note: req.dry_run ? 'Dry run — nothing sent.' : (queue.length ? `Sending ${queue.length} in the background, ${$env.FUNNEL_PAUSE_SECONDS || 30}s apart. Poll status.` : 'Nothing to send.') };
return [{ json: { response, queue: req.dry_run ? [] : queue } }];

const q = $('One at a time').first().json;
const out = $input.first().json || {};
const ok = !out.error;
const rec = { at: new Date().toISOString().slice(0, 19) + 'Z', campaign: q.campaign, email: q.email, segment: q.segment, via: 'email-studio', ok, error: ok ? null : String(out.error.message || JSON.stringify(out.error)).slice(0, 300) };
return [{ json: { ...rec, log_b64: Buffer.from(JSON.stringify(rec) + '\n').toString('base64') } }];
